                                                                                                                                                                                                          
  CREATE TABLE "TENANT_RICH_TEXT"                                                                                                                                                              
   (	"RICH_TEXT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                               
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                    
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                               
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                      
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                      
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                 
	"CODE" NVARCHAR2(256) NOT NULL ENABLE,                                                                                                                                                                   
	"TITLE" NVARCHAR2(256) NOT NULL ENABLE,                                                                                                                                                                  
	"SUBTITLE" NVARCHAR2(256),                                                                                                                                                                               
	"CONTENT" CLOB NOT NULL ENABLE,                                                                                                                                                                          
	"LANGUAGE_TYPE" NVARCHAR2(20) DEFAULT 'HTML' NOT NULL ENABLE,                                                                                                                                            
	"CONTENT_RAW" CLOB NOT NULL ENABLE,                                                                                                                                                                      
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                            
	 PRIMARY KEY ("RICH_TEXT_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                    
	 CONSTRAINT "LANGUAGE_TYPE_OPTIONAL_VALUES" CHECK (LANGUAGE_TYPE in ('HTML', 'MARKDOWN')) ENABLE                                                                                                         
   ) ;                                                                                                                                                                                                    

